// TypeScript Version: 4.1

/// <reference types="@stdlib/types"/>

import { Collection, AccessorArrayLike } from '@stdlib/types/array';
import { Mode } from '@stdlib/types/ndarray';

/**
* Index array.
*/
type IndexArray = Collection<number> | AccessorArrayLike<number>;

/**
* Callback function invoked for each indexed element.
*/
type Callback<T, U, V> = ( this: V, value: T, index: number ) => U;

/**
* Interface describing `takeMap`.
*/
interface TakeMap {
	/**
	* Takes elements from an array based on an index array and applies a callback function to each element.
	*
	* @param x - input array
	* @param indices - list of element indices
	* @param mode - index mode
	* @param clbk - callback function
	* @param thisArg - callback execution context
	* @returns output array
	*
	* @example
	* var x = [ 1, 2, 3, 4 ];
	*
	* function clbk( v ) {
	*     return v * 2;
	* }
	*
	* var y = takeMap( x, [ 1, 3 ], 'throw', clbk );
	* // returns [ 4, 8 ]
	*/
	<T = unknown, U = unknown, V = unknown>( x: Collection<T>, indices: IndexArray, mode: Mode, clbk: Callback<T, U, V>, thisArg?: ThisParameterType<Callback<T, U, V>> ): Array<U>;

	/**
	* Takes elements from an array based on an index array and applies a callback function to each element. The function assigns the transformed values to elements in a provided output array.
	*
	* @param x - input array
	* @param indices - list of element indices
	* @param mode - index mode
	* @param clbk - callback function
	* @param out - output array
	* @param stride - output array stride
	* @param offset - output array offset
	* @param thisArg - callback execution context
	* @returns output array
	*
	* @example
	* var x = [ 1, 2, 3, 4 ];
	* var out = [ 0, 0, 0, 0 ];
	*
	* function clbk( v ) {
	*     return v * 2;
	* }
	*
	* var arr = takeMap.assign( x, [ 1, 3 ], 'throw', clbk, out, 2, 0 );
	* // returns [ 4, 0, 8, 0 ]
	*
	* var bool = ( arr === out );
	* // returns true
	*/
	assign<T = unknown, U = unknown, V = unknown>( x: Collection<T> | AccessorArrayLike<T>, indices: IndexArray, mode: Mode, clbk: Callback<T, U, V>, out: Collection<U>, stride: number, offset: number, thisArg?: ThisParameterType<Callback<T, U, V>> ): Collection<U>;

	/**
	* Takes elements from an array based on an index array and applies a callback function to each element. The function assigns the transformed values to elements in a provided output array.
	*
	* @param x - input array
	* @param indices - list of element indices
	* @param mode - index mode
	* @param clbk - callback function
	* @param out - output array
	* @param stride - output array stride
	* @param offset - output array offset
	* @param thisArg - callback execution context
	* @returns output array
	*
	* @example
	* var toAccessorArray = require( '@stdlib/array/base/to-accessor-array' );
	*
	* var x = toAccessorArray( [ 1, 2, 3, 4 ] );
	* var out = toAccessorArray( [ 0, 0, 0, 0 ] );
	*
	* function clbk( v ) {
	*     return v * 2;
	* }
	*
	* var arr = takeMap.assign( x, [ 1, 3 ], 'throw', clbk, out, 2, 0 );
	*
	* var v = arr.get( 0 );
	* // returns 4
	*/
	assign<T = unknown, U = unknown, V = unknown>( x: Collection<T> | AccessorArrayLike<T>, indices: IndexArray, mode: Mode, clbk: Callback<T, U, V>, out: AccessorArrayLike<U>, stride: number, offset: number, thisArg?: ThisParameterType<Callback<T, U, V>> ): AccessorArrayLike<U>;
}


// MAIN //

/**
* Takes elements from an array based on an index array and applies a callback function to each element.
*
* @param x - input array
* @param indices - list of element indices
* @param mode - index mode
* @param clbk - callback function
* @param thisArg - callback execution context
* @returns output array
*
* @example
* var x = [ 1, 2, 3, 4 ];
*
* function clbk( v ) {
*     return v * 2;
* }
*
* var y = takeMap( x, [ 1, 3 ], 'throw', clbk );
* // returns [ 4, 8 ]
*/
declare var takeMap: TakeMap;


// EXPORTS //

export = takeMap;
